from pathlib import Path

p = Path('script.js')
s = p.read_text(encoding='utf-8')

old_panel = ".cta-panel{position:relative!important;min-height:510px!important;padding:76px 68px!important;display:flex!important;flex-direction:column!important;justify-content:center!important;align-items:flex-start!important;text-align:left!important;border:1px solid rgba(230,200,120,.34)!important;border-radius:20px!important;overflow:hidden!important;background:#0e0d0b!important;box-shadow:0 38px 100px rgba(0,0,0,.44),0 0 0 1px rgba(201,162,75,.035),inset 0 1px 0 rgba(230,200,120,.11),inset 0 0 0 1px rgba(255,255,255,.018)!important}"
new_panel = ".cta-panel{position:relative!important;min-height:510px!important;padding:76px 68px!important;display:flex!important;flex-direction:column!important;justify-content:center!important;align-items:flex-start!important;text-align:left!important;border:1px solid rgba(230,200,120,.34)!important;border-radius:20px!important;overflow:hidden!important;background:#17120c!important;box-shadow:0 38px 100px rgba(0,0,0,.44),0 0 0 1px rgba(201,162,75,.035),inset 0 1px 0 rgba(230,200,120,.11),inset 0 0 0 1px rgba(255,255,255,.018)!important}"

old_before = ".cta-panel::before{content:''!important;position:absolute!important;inset:-12%!important;background-image:url('assets/cta-final-hq.webp')!important;background-repeat:no-repeat!important;background-position:right center!important;background-size:cover!important;filter:blur(34px) brightness(.42) saturate(.88)!important;transform:scale(1.10)!important;transform-origin:right center!important;opacity:.82!important;pointer-events:none!important;z-index:0!important;-webkit-mask-image:none!important;mask-image:none!important}"
new_before = ".cta-panel::before{content:''!important;position:absolute!important;inset:0!important;background:#17120c!important;pointer-events:none!important;z-index:0!important}"

old_main = ".cta-photo-main{position:absolute!important;inset:0!important;background-image:url('assets/cta-final-hq.webp')!important;background-repeat:no-repeat!important;background-position:right center!important;background-size:auto 100%!important;filter:brightness(.99) contrast(1.03) saturate(1.01)!important;pointer-events:none!important;z-index:1!important;-webkit-mask-image:linear-gradient(90deg,transparent 0%,transparent 43%,rgba(0,0,0,.04) 48%,rgba(0,0,0,.10) 53%,rgba(0,0,0,.20) 58%,rgba(0,0,0,.34) 63%,rgba(0,0,0,.50) 68%,rgba(0,0,0,.66) 73%,rgba(0,0,0,.80) 78%,rgba(0,0,0,.90) 83%,rgba(0,0,0,.97) 88%,#000 93%,#000 100%)!important;mask-image:linear-gradient(90deg,transparent 0%,transparent 43%,rgba(0,0,0,.04) 48%,rgba(0,0,0,.10) 53%,rgba(0,0,0,.20) 58%,rgba(0,0,0,.34) 63%,rgba(0,0,0,.50) 68%,rgba(0,0,0,.66) 73%,rgba(0,0,0,.80) 78%,rgba(0,0,0,.90) 83%,rgba(0,0,0,.97) 88%,#000 93%,#000 100%)!important;mask-image:linear-gradient(90deg,transparent 0%,transparent 43%,rgba(0,0,0,.04) 48%,rgba(0,0,0,.10) 53%,rgba(0,0,0,.20) 58%,rgba(0,0,0,.34) 63%,rgba(0,0,0,.50) 68%,rgba(0,0,0,.66) 73%,rgba(0,0,0,.80) 78%,rgba(0,0,0,.90) 83%,rgba(0,0,0,.97) 88%,#000 93%,#000 100%)!important}"
new_main = ".cta-photo-main{position:absolute!important;inset:0!important;background-image:url('assets/cta-final-hq.webp')!important;background-repeat:no-repeat!important;background-position:right center!important;background-size:auto 100%!important;filter:brightness(.99) contrast(1.03) saturate(1.01)!important;pointer-events:none!important;z-index:1!important;-webkit-mask-image:linear-gradient(90deg,transparent 0%,transparent 54%,rgba(0,0,0,.08) 58%,rgba(0,0,0,.22) 62%,rgba(0,0,0,.42) 66%,rgba(0,0,0,.64) 70%,rgba(0,0,0,.82) 74%,rgba(0,0,0,.94) 78%,#000 82%,#000 100%)!important;mask-image:linear-gradient(90deg,transparent 0%,transparent 54%,rgba(0,0,0,.08) 58%,rgba(0,0,0,.22) 62%,rgba(0,0,0,.42) 66%,rgba(0,0,0,.64) 70%,rgba(0,0,0,.82) 74%,rgba(0,0,0,.94) 78%,#000 82%,#000 100%)!important}"

old_after = ".cta-panel::after{content:''!important;position:absolute!important;inset:0!important;background:radial-gradient(58% 118% at 86% 45%,rgba(230,200,120,.055) 0%,rgba(201,162,75,.014) 35%,transparent 70%),linear-gradient(180deg,rgba(255,255,255,.010) 0%,transparent 24%,transparent 74%,rgba(0,0,0,.16) 100%),linear-gradient(90deg,#0e0d0b 0%,rgba(14,13,11,.995) 22%,rgba(14,13,11,.97) 30%,rgba(14,13,11,.90) 38%,rgba(14,13,11,.78) 46%,rgba(14,13,11,.62) 54%,rgba(14,13,11,.45) 62%,rgba(14,13,11,.29) 70%,rgba(14,13,11,.16) 78%,rgba(14,13,11,.07) 86%,rgba(14,13,11,.02) 93%,rgba(14,13,11,0) 100%)!important;pointer-events:none!important;z-index:2!important}"
new_after = ".cta-panel::after{content:''!important;position:absolute!important;inset:0!important;background:radial-gradient(54% 115% at 86% 44%,rgba(230,200,120,.045) 0%,rgba(201,162,75,.012) 36%,transparent 72%),linear-gradient(180deg,rgba(255,255,255,.008) 0%,transparent 24%,transparent 76%,rgba(0,0,0,.14) 100%)!important;pointer-events:none!important;z-index:2!important}"

for old, new, label in [(old_panel,new_panel,'panel'),(old_before,new_before,'before'),(old_main,new_main,'main'),(old_after,new_after,'after')]:
    if old not in s:
        raise SystemExit('Expected CTA fragment not found: ' + label)
    s = s.replace(old, new, 1)

p.write_text(s, encoding='utf-8')
